import csv
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP

rows={}
with open('/app/input/table_health.csv', newline='') as f:
    for r in csv.DictReader(f):
        if r['table_name'] not in rows:
            rows[r['table_name']]=r

reindex={}
with open('/app/input/reindex_log.csv', newline='') as f:
    for r in csv.DictReader(f):
        reindex[r['table_name']]=r

def days(d):
    return (datetime.fromisoformat(rows[d]['audit_date']) - datetime.fromisoformat(rows[d]['last_analyzed'])).days

out=[]
for t,r in rows.items():
    tp=int(r['total_pages'])
    dp=int(r['dead_pages'])
    ratio=(Decimal(dp)/Decimal(tp)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    size='large' if tp>=500 else 'small'
    cap=Decimal('0.2') if size=='large' else Decimal('0.4')
    stale=days(t)>30
    if stale:
        cap=cap-Decimal('0.05')
    av_disabled = (r['vacuum_type']=='manual' or r['autovacuum_enabled'].lower()!='true')
    ri=reindex.get(t)
    exempt = False
    if r['maintenance_active'].lower()=='true' and ri and ri['approved'].lower()=='true' and datetime.fromisoformat(ri['valid_until'])>=datetime.fromisoformat(r['audit_date']):
        exempt=True
    if av_disabled:
        finding='AUTOVACUUM_DISABLED'
    elif not exempt and ratio>cap:
        finding='BLOAT_THRESHOLD_EXCEEDED'
    elif stale:
        finding='STALE_STATISTICS'
    else:
        finding='none'
    out.append((r['last_analyzed'], t, size, ratio, cap, stale, days(t), exempt, r['maintenance_active'], ri, finding))

for row in sorted(out, key=lambda x:(x[0], x[1])):
    print(row)
